application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #eef3f8;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
  min-width: 0;
}

.quiz-shell {
  width: min(100% - 2rem, 760px);
  margin: 0 auto;
  padding: 2.5rem 0 3rem;
}

.quiz-header {
  margin-bottom: 1.75rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: #245b8f;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(2rem, 5vw, 3rem);
  line-height: 1.1;
}

.quiz-header > p:last-child {
  margin-bottom: 0;
  color: #435267;
}

.question,
.result {
  margin: 0 0 1.25rem;
  padding: 1.25rem;
  border: 1px solid #c8d3df;
  border-radius: .75rem;
  background: #fff;
}

.question legend {
  max-width: 100%;
  padding: 0 .25rem;
  font-size: 1.1rem;
  font-weight: 700;
}

.options {
  display: grid;
  gap: .65rem;
  margin-top: 1rem;
}

.option {
  display: flex;
  align-items: center;
  gap: .7rem;
  padding: .75rem .85rem;
  border: 1px solid #aebdca;
  border-radius: .5rem;
  cursor: pointer;
}

.option:hover {
  border-color: #245b8f;
  background: #f1f7fc;
}

.option:has(input:checked) {
  border-color: #174a78;
  background: #e5f0fa;
}

.option input {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: #174a78;
}

button {
  border: 0;
  border-radius: .5rem;
  padding: .8rem 1.2rem;
  color: #fff;
  background: #174a78;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

button:hover {
  background: #103858;
}

button:focus-visible,
input:focus-visible,
.option:has(input:focus-visible) {
  outline: 3px solid #f1a928;
  outline-offset: 3px;
}

.actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin: 1.5rem 0 2rem;
}

.status,
.question-error {
  color: #a12626;
  font-weight: 600;
}

.status {
  margin: 0;
}

.question-error {
  min-height: 1.5em;
  margin: .5rem 0 0;
  font-size: .9rem;
}

.result {
  border-left: .35rem solid #245b8f;
}

.result h2 {
  margin-bottom: .35rem;
  font-size: 1.2rem;
}

.score {
  margin-bottom: 0;
  font-size: 1.35rem;
  font-weight: 700;
}

@media (max-width: 480px) {
  .quiz-shell {
    width: min(100% - 1rem, 760px);
    padding-top: 1.5rem;
  }

  .question,
  .result {
    padding: 1rem;
  }
}

application.javascript:
const form = document.querySelector('#quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const statusElement = document.querySelector('#form-status');

const correctAnswers = {
  'question-1': 'mars',
  'question-2': 'photosynthesis',
  'question-3': 'six'
};

function getQuestionNames() {
  return Object.keys(correctAnswers);
}

function getSelectedAnswer(questionName) {
  const selected = form.querySelector(`input[name="${questionName}"]:checked`);
  return selected ? selected.value : null;
}

function clearValidation() {
  getQuestionNames().forEach((questionName) => {
    const error = document.querySelector(`#${questionName}-error`);
    error.textContent = '';
  });
  statusElement.textContent = '';
}

function validateAnswers() {
  let isValid = true;
  let firstMissingInput = null;

  getQuestionNames().forEach((questionName) => {
    const error = document.querySelector(`#${questionName}-error`);
    const selected = getSelectedAnswer(questionName);
    error.textContent = '';

    if (!selected) {
      isValid = false;
      error.textContent = 'Please choose an answer.';
      if (!firstMissingInput) {
        firstMissingInput = form.querySelector(`input[name="${questionName}"]`);
      }
    }
  });

  if (firstMissingInput) {
    firstMissingInput.focus();
  }
  return isValid;
}

function calculateScore() {
  return getQuestionNames().reduce((score, questionName) => {
    return score + (getSelectedAnswer(questionName) === correctAnswers[questionName] ? 1 : 0);
  }, 0);
}

function displayScore(score) {
  scoreElement.textContent = `${score} out of 3`;
  scoreElement.dataset.score = String(score);
  statusElement.textContent = 'Quiz submitted.';
}

function handleSubmit(event) {
  event.preventDefault();
  clearValidation();

  if (!validateAnswers()) {
    statusElement.textContent = 'Complete all questions before submitting.';
    return;
  }

  displayScore(calculateScore());
}

form.addEventListener('submit', handleSubmit);
